SELECT t.Reval_ID, CAST(t.Reval_Smpl_Run_ID AS VARCHAR(250)) AS Reval_Smpl_Run_ID, t.Reval_Project_Cd, t.Reval_Table_Nm, t.Reval_Run_Ty, t.Reval_Run_Key, t.Reval_As_Of_Dt_Key, t.Source_As_Of_Dtts, t.Reval_Dtts, t.Reval_Triggered_By, t.Reval_Stat, t.Orig_Selected_Cnt, t.Replay_Selected_Cnt, t.Same_Cnt, t.Only_Orig_Cnt, t.Only_Replay_Cnt, t.Missing_Cnt, t.Diff_Txt, t.Engine_Version_Txt, t.Reval_Error_Txt, t.Signoff_By, t.Signoff_Dtts, t.Signoff_Txt, t.Signed_Off, t.Match_Ind, t.Days_To_Signoff, t.Reval_Cnt
FROM (
SELECT v.Reval_ID, v.Smpl_Run_ID AS Reval_Smpl_Run_ID, v.Project_Cd AS Reval_Project_Cd, v.Table_Nm AS Reval_Table_Nm, v.Run_Ty AS Reval_Run_Ty, v.Run_Key AS Reval_Run_Key, v.As_Of_Dt_Key AS Reval_As_Of_Dt_Key, v.Source_As_Of_Dtts, v.Reval_Dtts, v.Triggered_By AS Reval_Triggered_By, v.Reval_Stat, v.Orig_Selected_Cnt, v.Replay_Selected_Cnt, v.Same_Cnt, v.Only_Orig_Cnt, v.Only_Replay_Cnt, v.Missing_Cnt, v.Diff_Txt, v.Engine_Version_Txt, v.Error_Txt AS Reval_Error_Txt, v.Signoff_By, v.Signoff_Dtts, v.Signoff_Txt, v.Signed_Off, v.Match_Ind, v.Days_To_Signoff, v.Reval_Cnt
FROM (
SELECT v.Reval_ID, v.Smpl_Run_ID, v.Project_Cd, v.Table_Nm, v.Run_Ty, v.Run_Key, v.As_Of_Dt_Key, v.Source_As_Of_Dtts, v.Reval_Dtts, v.Triggered_By, v.Reval_Stat, v.Orig_Selected_Cnt, v.Replay_Selected_Cnt, v.Same_Cnt, v.Only_Orig_Cnt, v.Only_Replay_Cnt, v.Missing_Cnt, v.Diff_Txt, v.Engine_Version_Txt, v.Error_Txt, v.Signoff_By, v.Signoff_Dtts, v.Signoff_Txt, CASE WHEN v.Signoff_By IS NULL THEN 'Waiting' ELSE 'Signed off' END AS Signed_Off, CASE WHEN v.Reval_Stat = 'MATCH' THEN 1 ELSE 0 END AS Match_Ind, CAST(v.Signoff_Dtts AS DATE) - CAST(v.Reval_Dtts AS DATE) AS Days_To_Signoff, 1 AS Reval_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRevalidation v
) v
) t
